/**
 * preload — Act-aware audio asset preloading (spec 11 §5).
 *
 * Maps each Act number to the set of SFX + music + ambience assets it
 * needs, then preloads them via SfxPool / MusicPlayer / AmbienceLayer.
 *
 * Spec 11 §5.2: 3 instances per SFX are preloaded per Act so rapid-fire
 * triggers (sword swings, footstep chains) don't queue on one instance.
 *
 * For now the manifest is a simple object literal in this file (per task
 * P1.E4.T5). A future task will swap it for a JSON manifest generated by
 * the bake script (spec 11 §9.1).
 */

import { logger } from '@/shared/log';

import { musicPlayer } from './MusicPlayer';
import { sfxPool } from './SfxPool';

/** Number of SFX instances to preload per sound id (spec 11 §5.2). */
export const SFX_INSTANCES_PER_SOUND = 3;

/** File path prefixes (relative to basePath = Sound.MAIN_BUNDLE). */
const SFX_PREFIX = 'sfx/';
const MUSIC_PREFIX = 'music/';
const AMBIENCE_PREFIX = 'ambience/';

/** Per-Act audio manifest. */
export interface ActAudioManifest {
  /** Music track ids (without extension) for this Act. */
  music?: string[];
  /** Ambience bed ids (without extension) for this Act. */
  ambience?: string[];
  /** SFX id → relative file path under `sfx/` for this Act. */
  sfx?: Record<string, string>;
}

