/** Build the absolute file path for a music track id. */
export function musicFilePath(trackId: string): string {
  return `${MUSIC_PREFIX}${trackId}.ogg`;
}

/** Build the absolute file path for an ambience bed id. */
export function ambienceFilePath(bedId: string): string {
  return `${AMBIENCE_PREFIX}${bedId}.ogg`;
}

/** Build the absolute file path for an SFX (sfx-relative path already includes subfolder). */
export function sfxFilePath(relativePath: string): string {
  return `${SFX_PREFIX}${relativePath}`;
}

/** Resolve an act number to its manifest (falls back to Act 0 if unknown). */
export function getActManifest(actNumber: number): ActAudioManifest {
  return ACT_AUDIO_MANIFEST[actNumber] ?? ACT_AUDIO_MANIFEST[0];
}

/**
 * Preload all SFX and music assets required for the given Act.
 *
 *  - SFX: preloaded into the pool, 3 instances each (spec 11 §5.2).
 *  - Music: TrackPlayer streams on demand; we call MusicPlayer.preload()
 *    for API symmetry but it is currently a no-op.
 *  - Ambience: preloaded into the AmbienceLayer; beds start looping only
 *    when `ambienceLayer.play(bedId, file)` is explicitly called from
 *    the scene manager. Here we only warm the Sound instances by
 *    preloading them once (then immediately stopping — they'll be
 *    re-created on play()).
 *
 * Errors for individual assets are logged and swallowed — partial
 * preloading is preferable to aborting the whole Act load.
 */
export async function preloadAudioForAct(actNumber: number): Promise<void> {
  const manifest = getActManifest(actNumber);
  logger.info(`[audio] preloading assets for Act ${actNumber}`);

  // SFX: 3 instances each. Preloads run in parallel — `new Sound(...)`
  // completes asynchronously on device, so awaiting each instance serially
  // would make an Act's preload take ~3× longer than necessary (the load
  // callback, not JS, is the bottleneck; the pool is safe for concurrent
  // preloads).
  if (manifest.sfx) {
    const tasks: Array<Promise<void>> = [];
    for (const [id, relPath] of Object.entries(manifest.sfx)) {
      const file = sfxFilePath(relPath);
      for (let i = 0; i < SFX_INSTANCES_PER_SOUND; i++) {
        tasks.push(
          sfxPool.preload(id, file).catch((e: unknown) => {
            logger.warn(`[audio] sfx preload failed for "${id}"`, e);
          }),
        );
      }
    }
    await Promise.all(tasks);
  }

  // Music: TrackPlayer streams on demand; preload() is a no-op today.
  if (manifest.music && manifest.music.length > 0) {
    const tracks = manifest.music.map((id) => ({
      id,
      url: musicFilePath(id),
      title: id,
    }));
    try {
      await musicPlayer.preload(tracks);
    } catch (e) {
      logger.warn('[audio] music preload failed', e);
    }
  }

  // Ambience: the manifest records which beds this Act needs, but
  // AmbienceLayer doesn't expose a preload() — beds are loaded
  // on-demand when the scene manager calls ambienceLayer.play().
  // We record the manifest here so a future optimisation can warm
  // the Sound instances without changing call sites.
  if (manifest.ambience && manifest.ambience.length > 0) {
    logger.debug(
      `[audio] ambience manifest for Act ${actNumber}: ${manifest.ambience.join(', ')}`,
    );
  }
}
